        state = "".join(config)
        if state in seen:
            return False # Cycle detected
        seen.add(state)

        # Check if stable
        # At most one boundary between A and C
        boundaries = 0
        for i in range(len(config) - 1):
            if config[i] != config[i+1]:
                boundaries += 1
        if boundaries <= 1:
            return True

        # Operation
        idx = k - 1
        coin = config[idx]

        # Find the range [L, R] of consecutive same coins containing idx
        L = idx
        while L > 0 and config[L-1] == coin:
